files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract works out where every member would land before it writes anything, so an archive it
refuses leaves the destination as it was.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_HOPS = 40  # links one path may pass through before it counts as a loop, the kernel's own limit


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, target in plan:
            write_member(tar, member, os.path.join(root, *target))
    return [paths.clean_name(m.name) for m in members]


def plan_members(root, members):
    """[(member, the destination parts it is written to), ...] once every member has passed, or UnsafeArchive.

    Nothing is written here. Each member is placed against the destination as the members before it leave it, with
    links followed the way the kernel follows them, so a member is only ever written into a real folder inside dest.
    Then every link is followed once more against the finished layout, because a later member can turn a name that an
    earlier link goes through into a link of its own (a -> b/../x, then b -> .)."""
    layout = _Layout(root)
    seen = set()
    plan = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        if member.issym():
            linkname = paths.clean_link(member.linkname, name)
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        *up, last = name.split("/")
        try:
            target = layout.walk((), up, creating=True) + (last,)
        except UnsafeArchive as e:
            raise UnsafeArchive(f"{name}: {e}") from None
        kind = layout.kind(target)
        if kind is not None and not (member.isdir() and kind == "dir"):
            raise UnsafeArchive(f"{name} is already in the destination")
        if member.isdir():
            layout.dirs.add(target)
        elif member.issym():
            layout.links[target] = linkname
        else:
            layout.files.add(target)
        plan.append((member, target))
    for target, linkname in layout.links.items():
        try:
            layout.walk(target[:-1], linkname.split("/"), creating=False)
        except UnsafeArchive as e:
            raise UnsafeArchive(f"{'/'.join(target)} -> {linkname}: {e}") from None
    return plan


class _Layout:
    """The destination as the members leave it: the archive's own folders, files and links, and whatever is already
    on disk. Names are tuples of parts relative to the destination. The disk is only read."""

    def __init__(self, root):
        self.root = root
        self.dirs = set()
        self.files = set()
        self.links = {}  # parts -> the link's target, as the member gives it

    def kind(self, parts):
        """"dir", "file", "link", or None when nothing is there."""
        if not parts or parts in self.dirs:
            return "dir"
        if parts in self.files:
            return "file"
        if parts in self.links:
            return "link"
        try:
            mode = os.lstat(os.path.join(self.root, *parts)).st_mode
        except (FileNotFoundError, NotADirectoryError):
            return None
        if stat.S_ISLNK(mode):
            return "link"
        return "dir" if stat.S_ISDIR(mode) else "file"

    def link_target(self, parts):
        if parts in self.links:
            return self.links[parts]
        return os.readlink(os.path.join(self.root, *parts))

    def walk(self, start, names, creating):
        """The folder that start followed by names leads to, followed the way the kernel follows it: a link is followed
        where it sits, so its target is relative to the folder holding it, and ".." goes up from where the path has got
        to. UnsafeArchive when that leads out of the destination, runs through a file or loops. When creating, the
        folders on the way are ones the archive will make, so missing ones are recorded as the archive's."""
        cur = tuple(start)
        pending = list(reversed(names))
        hops = 0
        while pending:
            part = pending.pop()
            if part in ("", "."):
                continue
            if part == "..":
                if not cur:
                    raise UnsafeArchive("leads outside the destination")
                cur = cur[:-1]
                continue
            here = cur + (part,)
            kind = self.kind(here)
            if kind == "link":
                hops += 1
                if hops > MAX_HOPS:
                    raise UnsafeArchive("loops through links")
                target = self.link_target(here)
                if target.startswith("/"):
                    raise UnsafeArchive("leads outside the destination")
                pending.extend(reversed(target.split("/")))
                continue
            if creating:
                if kind == "file":
                    raise UnsafeArchive("goes through a file")
                if kind is None:
                    self.dirs.add(here)
            cur = here
        return cur


def write_member(tar, member, path):
    if member.isdir():
        os.makedirs(path, exist_ok=True)
        return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, path)
        return
    with tar.extractfile(member) as src, open(path, "xb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(path, EXEC_MODE if member.mode & 0o100 else FILE_MODE)

