from billing import rules


def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    result = {account_id: 0 for (account_id,) in conn.execute("SELECT id FROM accounts")}

    # Payments on non-voided invoices that rules.counts accepts, grouped by invoice, in id order.
    counted = {}
    for invoice_id, paid, status, method in conn.execute(
            "SELECT p.invoice_id, p.amount_cents, p.status, p.method "
            "FROM payments p JOIN invoices i ON i.id = p.invoice_id "
            "WHERE i.voided = 0 ORDER BY p.id"):
        if rules.counts(status, method):
            counted.setdefault(invoice_id, []).append(paid)

    # Invoices in id order, so each account accumulates in the same order as before.
    # Invoices whose account is not in accounts are skipped, as the per-account loop did.
    for invoice_id, account_id, cents in conn.execute(
            "SELECT id, account_id, amount_cents FROM invoices WHERE voided = 0 ORDER BY id"):
        if account_id not in result:
            continue
        result[account_id] += cents
        for paid in counted.get(invoice_id, ()):
            result[account_id] -= paid
    return result

