"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.
"""
import heapq
import json
import os
import shutil
import tempfile

from . import kinds, money, timefmt, v2, v3
from .accounts import load as load_accounts
from .errors import FormatError, MigrationError

# Records held in memory at once while sorting. Each full run goes to a file, so a whole export never has to fit in
# memory. While merging, each run is one open file, so this also caps the open files: about 80 for 40 million lines.
RUN_SIZE = 500_000


def migrate(src, accounts, dst):
    """Write the v3 file at dst for the v2 export at src, using the accounts file at accounts; return the number of
    records written. A line that can't be migrated raises MigrationError naming it, and dst is left alone."""
    held = load_accounts(accounts)
    # The work files sit beside dst, so the finished file can be moved into place with os.replace.
    work = tempfile.mkdtemp(prefix=".migrate-", dir=os.path.dirname(os.path.abspath(dst)))
    try:
        # Every line is converted, superseded revisions included, so a bad line stops the migration whichever
        # revision it is. Sorted by id, then revision, then line, each entry's current line is last in its group.
        by_id = _external_sort(_convert_lines(src, held), _id_rev_line, work, "id")
        records = _external_sort(_current(by_id), v3.order_key, work, "order")
        out = os.path.join(work, "ledger_v3.jsonl")
        count = _write(out, records)
        os.replace(out, dst)
        return count
    finally:
        shutil.rmtree(work, ignore_errors=True)


def _convert_lines(src, held):
    """(id, revision, line number, v3 record) for every non-blank line of the export, in file order."""
    with open(src, "rb") as f:
        for number, raw in enumerate(f, 1):
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError as e:
                raise MigrationError(f"not UTF-8 ({e.reason})", number) from None
            if number == 1 and text.startswith("﻿"):
                text = text[1:]  # a byte order mark is not part of the content
            if not text.strip():
                continue
            try:
                record = json.loads(text)
            except ValueError as e:
                raise MigrationError(f"not JSON ({e})", number) from None
            entry = _convert(record, number, held)
            yield [entry["id"], entry["source_rev"], number, entry]


def _convert(record, number, held):
    """The v3 record for one v2 line; MigrationError naming the line when it can't be migrated."""
    try:
        v2.check(record, None)
    except FormatError as e:
        raise MigrationError(str(e), number) from None
    account = held.get(record["account"])
    if account is None:
        raise MigrationError(f"account {record['account']!r} isn't in the accounts file", number)
    entry_type = kinds.LEGACY.get(record["kind"], record["kind"])
    if entry_type not in kinds.TYPES:
        raise MigrationError(f"unknown kind {record['kind']!r}", number)
    # A null currency is the account's own; a given one is the entry's, even when it differs from the account's.
    currency = account.currency if record["currency"] is None else record["currency"]
    amount = record["amount"]
    if amount.startswith("-"):
        raise MigrationError(f"amount {amount!r} is negative; amounts are positive and the kind gives the sign",
                             number)
    try:
        minor = _minor_units(amount, currency)
        stamp = timefmt.parse_ts(record["ts"])
        if stamp.tzinfo is None:
            # Without an offset the time is the account's local time, at the account's utc_offset.
            stamp = stamp.replace(tzinfo=account.tz)
        posted_at = timefmt.to_utc_z(stamp)
    except (ValueError, OverflowError) as e:
        raise MigrationError(str(e), number) from None
    out = {"id": record["id"], "account": record["account"], "type": entry_type,
           "amount_minor": kinds.SIGN[entry_type] * minor, "currency": currency, "posted_at": posted_at,
           "memo": record["memo"], "source_rev": record["rev"]}
    try:
        v3.validate(out)
    except FormatError as e:
        raise MigrationError(str(e), number) from None
    return out


def _minor_units(amount, currency):
    """A positive plain decimal as whole minor units of currency, exactly. money.to_minor goes through Decimal, which
    rounds past 28 significant digits, so it can't be trusted for long amounts; the places check matches its rule."""
    if not money.PLAIN.fullmatch(amount):
        raise ValueError(f"not a plain decimal: {amount!r}")
    whole, _, fraction = amount.partition(".")
    places = money.exponent(currency)
    fraction = fraction.rstrip("0")
    if len(fraction) > places:
        raise ValueError(f"{amount} has more decimal places than {currency} allows")
    return int(whole + fraction.ljust(places, "0"))


def _id_rev_line(item):
    return item[0], item[1], item[2]


def _current(by_id):
    """Each entry's current record: the last line of its id's group."""
    last = None
    for item in by_id:
        if last is not None and last[0] != item[0]:
            yield last[3]
        last = item
    if last is not None:
        yield last[3]


def _external_sort(items, key, work, prefix):
    """The items in key order. They are sorted RUN_SIZE at a time, each run spilled to a file in work, then merged."""
    runs, buf = [], []

    def spill():
        buf.sort(key=key)
        path = os.path.join(work, f"{prefix}-{len(runs)}.jsonl")
        with open(path, "w", encoding="ascii") as f:
            for item in buf:
                f.write(json.dumps(item, separators=(",", ":")) + "\n")
        runs.append(path)
        buf.clear()

    for item in items:
        buf.append(item)
        if len(buf) >= RUN_SIZE:
            spill()
    if not runs:
        buf.sort(key=key)
        return iter(buf)
    if buf:
        spill()
    return heapq.merge(*(_read_run(path) for path in runs), key=key)


def _read_run(path):
    with open(path, encoding="ascii") as f:
        for line in f:
            yield json.loads(line)


def _write(path, records):
    count = 0
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        for record in records:
            f.write(v3.dump_line(record))
            count += 1
    return count

