from payments import gateway


class UnknownCustomer(Exception):
    pass


class KeyReused(Exception):
    """The idempotency key belongs to an earlier payment with a different customer or amount."""


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, an earlier payment stored under that key is returned
    without a charge when customer_id and cents match it, and KeyReused is raised
    when they do not. A request that fails (UnknownCustomer, Declined) stores
    nothing, so retrying it with the same key runs it again.

    Keyed calls must not run inside a transaction the caller has open: they begin
    one with BEGIN IMMEDIATE, which takes the database write lock before the key
    lookup. A concurrent request with the same key waits on that lock and then
    finds the payment, so it cannot charge twice.
    """
    if idempotency_key is None:
