"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, target in plan:
            write_member(tar, member, target)
    return [paths.clean_name(m.name) for m in members]


MAX_LINK_HOPS = 40

DIR, FILE, OTHER = "dir", "file", "other"


class _Tree:
    """What dest will hold once the planned members are written: the archive's members as they are planned, on top
    of what is already on disk. Paths are tuples of names relative to root, with every link already followed, so a
    path here never passes through a link. Links are resolved the way the OS resolves them (a link is followed
    before a ".." after it is applied), not lexically."""

    def __init__(self, root):
        self.root = root
        self.planned = {}  # path -> DIR | FILE | ("link", linkname)
        self.links = []  # [(name, the folder the link is in, linkname), ...] for the archive's links

    def lookup(self, path):
        if path in self.planned:
            return self.planned[path]
        try:
            st = os.lstat(os.path.join(self.root, *path))
        except FileNotFoundError:
            return None
        except NotADirectoryError:
            return OTHER
        if stat.S_ISLNK(st.st_mode):
            return ("link", os.readlink(os.path.join(self.root, *path)))
        if stat.S_ISDIR(st.st_mode):
            return DIR
        return FILE if stat.S_ISREG(st.st_mode) else OTHER

    def resolve(self, name, start, parts, hops=None):
        """The path that parts, taken from the folder start, leads to, following every link on the way.
        UnsafeArchive if it leaves root at any step, or names an absolute path, or goes round a link loop."""
        hops = hops if hops is not None else [0]
        cur = list(start)
        for part in parts:
            if part in ("", "."):
                continue
            if part == "..":
                if not cur:
                    raise UnsafeArchive(f"{name} leads outside the destination")
                cur.pop()
                continue
            node = self.lookup(tuple(cur) + (part,))
            if isinstance(node, tuple):
                hops[0] += 1
                if hops[0] > MAX_LINK_HOPS:
                    raise UnsafeArchive(f"{name} goes round a loop of links")
                linkname = node[1]
                if not linkname or linkname.startswith("/") or "\x00" in linkname:
                    raise UnsafeArchive(f"{name} leads to an absolute path")
                cur = list(self.resolve(name, tuple(cur), linkname.split("/"), hops))
            else:
                cur.append(part)
        return tuple(cur)

    def check_link(self, name, parent, linkname):
        """UnsafeArchive unless the link name, in the folder parent and pointing at linkname, leads inside root."""
        try:
            self.resolve(name, parent, linkname.split("/"))
        except UnsafeArchive as e:
            why = "which goes round a loop of links" if "loop" in str(e) else "outside the destination"
            raise UnsafeArchive(f"{name} links to {linkname}, {why}") from None

    def make_parents(self, name, parent):
        """Note that the folders down to parent will exist; UnsafeArchive if one of them is something else."""
        for i in range(1, len(parent) + 1):
            prefix = parent[:i]
            node = self.lookup(prefix)
            if node is None:
                self.planned[prefix] = DIR
            elif node != DIR:
                raise UnsafeArchive(f"{name} would be written inside {'/'.join(prefix)}, which isn't a folder")


def plan_members(root, members):
    """[(member, the absolute path it goes to), ...] once every member has passed, or UnsafeArchive.

    Every member is placed in a model of the destination in archive order, so a member written through a link an
    earlier member made is checked where it really lands, and every link is checked against the finished tree, so
    a link made later can't change where an earlier one leads."""
    seen = set()
    plan = []
    tree = _Tree(root)
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        if not (member.isfile() or member.isdir() or member.issym()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        parts = name.split("/")
        parent = tree.resolve(name, (), parts[:-1])
        tree.make_parents(name, parent)
        final = parent + (parts[-1],)
        node = tree.lookup(final)
        if member.isdir():
            if node not in (None, DIR):
                raise UnsafeArchive(f"{name} is a folder in place of something else")
            tree.planned[final] = DIR
        elif node is not None:
            raise UnsafeArchive(f"{name} would replace something already there")
        elif member.isfile():
            tree.planned[final] = FILE
        else:
            linkname = member.linkname
            if not linkname or linkname.startswith("/") or os.path.isabs(linkname) or "\x00" in linkname:
                raise UnsafeArchive(f"{name} links to an absolute path")
            tree.planned[final] = ("link", linkname)
            tree.links.append((name, parent, linkname))
            tree.check_link(name, parent, linkname)
        target = os.path.join(root, *final)
        if not paths.is_within(root, os.path.normpath(target)):
            raise UnsafeArchive(f"{name} would be written outside the destination")
        plan.append((member, target))
    for name, parent, linkname in tree.links:
        tree.check_link(name, parent, linkname)
    return plan


def write_member(tar, member, target):
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
    with tar.extractfile(member) as src, os.fdopen(fd, "wb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(target, EXEC_MODE if member.mode & 0o100 else FILE_MODE)

