from payments import gateway


class UnknownCustomer(Exception):
    pass


class IdempotencyKeyReused(Exception):
    pass


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already recorded under that key is returned
    as it was, provided it has the same customer and cents. Otherwise IdempotencyKeyReused
    is raised. The lookup, charge and insert run in one write transaction, so two requests
    with the same key cannot both charge.
    """
    if idempotency_key is None:
        return _record(conn, customer_id, cents, None)
    conn.execute("BEGIN IMMEDIATE")
    try:
        stored = _find_by_key(conn, idempotency_key)
        if stored is None:
            try:
                return _record(conn, customer_id, cents, idempotency_key)
            except sqlite3.IntegrityError:
                # Backstop for a key recorded behind our lookup. Undo this attempt's charge and insert.
                conn.rollback()
                stored = _find_by_key(conn, idempotency_key)
                if stored is None:
                    raise
        conn.rollback()  # nothing was written in this attempt; release the write lock
        if stored["customer_id"] != customer_id or stored["cents"] != cents:
            raise IdempotencyKeyReused(idempotency_key)
        return stored
    except BaseException:
        conn.rollback()
        raise


