    row = conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                       (idempotency_key,)).fetchone()
    if row is None:
        return None
    payment_id, customer_id, cents, charge_id = row
    return {"id": payment_id, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}

