    """An idempotency key was sent again with a different request body."""


def _payment_dict(row):
    return {"id": row["id"], "customer_id": row["customer_id"], "cents": row["cents"],
            "charge_id": row["charge_id"]}


def _replay(conn, idempotency_key, customer_id, cents):
    """Return the stored payment for this key, None if there is none, or raise KeyReused."""
    row = conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                       (idempotency_key,)).fetchone()
    if row is None:
        return None
    if (row["customer_id"], row["cents"]) != (customer_id, cents):
        raise KeyReused(idempotency_key)
    return _payment_dict(row)


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency key, a payment already stored under that key for the same
    customer and amount is returned without charging again; a payment stored under
    that key for a different customer or amount raises KeyReused. The lookup, the
    charge and the insert run in one write transaction (BEGIN IMMEDIATE), so two
    requests with the same key cannot both charge.
